// Conditional button example
function ConditionalButton() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  return (
    <div>
      {isLoggedIn && (
        <button onClick={() => setIsLoggedIn(false)}>
          Logout
        </button>
      )}
    </div>
  );
}

